ACCEPT_JS = """
(()=>{
 'use strict';const $=s=>document.querySelector(s);let token=new URLSearchParams(location.hash.slice(1)).get('t')||'',valid=false,busy=false;history.replaceState(null,'',location.pathname);
 const messages={'username already exists':'Dieser Benutzername ist bereits vergeben. Bitte wähle einen anderen.','username is not allowed':'Bitte wähle einen zulässigen Benutzernamen mit 2 bis 64 Zeichen.','display name or email is invalid':'Bitte prüfe deinen Namen und deine E-Mail-Adresse.','password must be 12–256 characters and contain no line breaks':'Das Passwort muss 12 bis 256 Zeichen lang sein und darf keine Zeilenumbrüche enthalten.','invitation is invalid, expired, revoked, or fully used':'Die Einladung ist nicht mehr gültig. Bitte fordere einen neuen Link an.','invitation is invalid or expired':'Die Einladung ist nicht mehr gültig. Bitte fordere einen neuen Link an.','invitation use limit reached':'Diese Einladung wurde bereits vollständig verwendet.'};
 async function post(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),path.endsWith('/redeem')?60000:20000);let response;try{response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),cache:'no-store',credentials:'same-origin',signal:controller.signal});const data=await response.json().catch(()=>null);if(!response.ok||!data){const error=new Error(data?.error||'server');error.status=response.status;error.uncertain=path.endsWith('/redeem')&&(response.ok||response.status>=500);throw error}return data}catch(error){if(!response)error.uncertain=path.endsWith('/redeem');throw error}finally{clearTimeout(timer)}}
 function fieldError(name,message){const input=$('[name="'+name+'"]'),out=$('#'+name+'-error');input.setAttribute('aria-invalid',String(!!message));out.textContent=message||'';out.hidden=!message}
 function invalidate(heading,text,retry=false){valid=false;$('#form').hidden=true;$('#invitation-validity').hidden=true;$('#status').textContent='Einladung prüfen';$('#accept-state').hidden=false;$('#accept-state').innerHTML='<div class="empty-state"><div class="empty-icon"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v6m0 3v1"/></svg></div><h3></h3><p></p>'+(retry?'<button class="button secondary" id="check-retry" type="button">Erneut prüfen</button>':'')+'</div>';$('#accept-state h3').textContent=heading;$('#accept-state p').textContent=text;$('#check-retry')?.addEventListener('click',check)}
 function setStep(step){['check','create','signin'].forEach((name,n)=>{const node=$('#step-'+name);node.className='step'+(n+1<step?' complete':n+1===step?' current':'');if(n+1===step)node.setAttribute('aria-current','step');else node.removeAttribute('aria-current')})}
 async function check(){if(!token){invalidate('Dieser Link ist unvollständig','Bitte öffne den vollständigen Einladungslink oder fordere eine neue Einladung an.');return}$('#accept-state').hidden=true;$('#status').textContent='Deine Einladung wird geprüft …';try{const data=await post('/onboarding/api/invite/check',{token});if(!data.valid){token='';invalidate('Einladung nicht mehr gültig','Der Link ist abgelaufen, wurde widerrufen oder bereits vollständig verwendet. Bitte fordere eine neue Einladung an.');return}valid=true;setStep(2);$('#status').textContent='Wähle deine Zugangsdaten. Danach kannst du dich bei Authelia anmelden.';const expiry=new Date(data.expires_at);$('#validity-text').textContent=Number.isNaN(expiry.getTime())?'Einladung gültig':'Einladung gültig bis '+new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'short',year:'numeric'}).format(expiry);$('#invitation-validity').hidden=false;$('#form').hidden=false}catch(_){invalidate('Einladung gerade nicht prüfbar','Die Verbindung konnte nicht hergestellt werden. Bitte versuche es gleich noch einmal.',true)}}
 function validate(){let first=null;for(const name of ['displayname','username','email','password','confirm']){const input=$('[name="'+name+'"]');let message='';if(!input.value.trim()&&name!=='password'&&name!=='confirm')message='Bitte fülle dieses Feld aus.';else if(!input.value)message='Bitte fülle dieses Feld aus.';else if(name==='displayname'&&input.value.trim().length>80)message='Verwende höchstens 80 Zeichen.';else if(name==='username'&&!/^[a-z0-9][a-z0-9._-]{1,63}$/.test(input.value))message='Verwende 2 bis 64 Zeichen: Kleinbuchstaben, Zahlen, Punkt, _ oder -.';else if(name==='email'&&!input.validity.valid)message='Bitte gib eine gültige E-Mail-Adresse ein.';else if((name==='password'||name==='confirm')&&(input.value.length<12||input.value.length>256||/[\\r\\n\\u0000]/.test(input.value)))message='Verwende 12 bis 256 Zeichen ohne Zeilenumbruch.';else if(name==='confirm'&&input.value!==$('[name="password"]').value)message='Die beiden Passwörter stimmen noch nicht überein.';fieldError(name,message);if(message&&!first)first=input}if(first){first.focus();return false}return true}
 document.querySelectorAll('[data-password]').forEach(button=>button.addEventListener('click',()=>{const input=$('#'+button.dataset.password),show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Verbergen':'Anzeigen';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',(button.dataset.password==='signup-confirm'?'Wiederholtes Passwort':'Passwort')+(show?' verbergen':' anzeigen'))}));
 $('#form').addEventListener('input',e=>{const name=e.target.name;if(['displayname','username','email','password','confirm'].includes(name)&&e.target.getAttribute('aria-invalid')==='true')fieldError(name,'')});
 $('#form').addEventListener('submit',async e=>{e.preventDefault();if(!valid||busy||!validate())return;const values=new FormData(e.target);busy=true;e.target.setAttribute('aria-busy','true');e.target.querySelectorAll('input,button').forEach(n=>n.disabled=true);$('#signup-submit').textContent='Konto wird erstellt …';$('#result').hidden=true;try{await post('/onboarding/api/invite/redeem',{token,username:values.get('username'),displayname:values.get('displayname'),email:values.get('email'),password:values.get('password')});token='';valid=false;e.target.reset();e.target.hidden=true;$('#status').hidden=true;$('#invitation-validity').hidden=true;$('#signup-complete').hidden=false;setStep(3);$('#signup-complete h2').tabIndex=-1;$('#signup-complete h2').focus()}catch(error){if(error.uncertain){valid=false;$('#result').textContent='Die Antwort ist ausgeblieben. Prüfe zuerst, ob du dich bereits anmelden kannst. Falls nicht, fordere Unterstützung an, bevor du es erneut versuchst.';$('#result').hidden=false;$('#signup-submit').textContent='Ergebnis unklar';const link=document.createElement('a');link.href='/';link.className='button secondary accept-submit';link.textContent='Anmeldung öffnen';$('#result').after(link)}else{const message=messages[error.message]||(error.status===429?'Zu viele Versuche. Bitte warte einen Moment.':'Dein Konto konnte gerade nicht erstellt werden. Bitte versuche es später noch einmal.');$('#result').textContent=message;$('#result').hidden=false;if(error.message==='username already exists'){fieldError('username',message)}else if(error.message.startsWith('invitation')){valid=false;token='';$('#signup-submit').textContent='Einladung nicht mehr gültig'}}}finally{busy=false;e.target.setAttribute('aria-busy','false');e.target.querySelectorAll('input,button:not(#signup-submit)').forEach(n=>n.disabled=false);$('#signup-submit').disabled=!valid;if(valid)$('#signup-submit').textContent='Konto erstellen';if($('#signup-username').getAttribute('aria-invalid')==='true')$('#signup-username').focus()}});
 check();
})();
""".encode("utf-8")

